/* world-data.js — embedded simplified world geometry (TopoJSON) so the
   globe works fully offline. Decoded at load into window.WORLD_TOPO. */
(function(){
  var b64="";
  try {
    var json = decodeURIComponent(escape(atob(b64)));
    window.WORLD_TOPO = JSON.parse(json);
  } catch(e){ console.warn("world-data decode failed", e); }
})();
